xsl:when.test:
(@producer_code_standard = 'ISBN10' or @producer_code_standard = 'ISBN13' or 
                                  @producer_code_standard = 'GTIN8' or @producer_code_standard = 'GTIN13' or 
                                  @producer_code_standard = 'GTIN14' or @producer_code_standard = 'GTIN12' or 
                                  @producer_code_standard = 'UPCE') and sizes/size/@code_producer!=''

xsl:for-each.select:
parameters/parameter[@hide='n' and 
                               value[1]/@name != '' and 
                               @name != 'Kod producenta' and 
                               @name != 'EAN'
                    and not(contains(@context_id, 'CONTEXT_STD'))
                    and not(contains($gender_nazwa_w_panelu, @name))
                    and not(contains($age_group_nazwa_w_panelu, @name))
                    and not(contains($kolor_nazwa_w_panelu, concat('|',translate(@name, $upperLetters, $lowerLetters),'|')))
                    ]
